"use strict";
const shopLocations=['counter','bench','bus','quay'];
let nightShop={visited:[],calls:[],returned:false,items:[],inspected:[],drawer:false,events:[],callStage:0},shopPlace='',shopFeedback='';
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop;if(p){nightShop.visited=shopLocations.filter(k=>p.visited?.includes(k));nightShop.calls=['answer','ask','hang'].filter(k=>p.calls?.includes(k));nightShop.returned=p.returned===true;nightShop.items=['key','receipt','case'].filter(k=>p.items?.includes(k));nightShop.inspected=['counter','tray','drawer','clock','door','poster','phone','case'].filter(k=>p.inspected?.includes(k));nightShop.drawer=p.drawer===true;nightShop.events=['ring','sms','second'].filter(k=>p.events?.includes(k));nightShop.callStage=[0,1,2].includes(p.callStage)?p.callStage:0;}}catch{}
const shopSaveBase=tideSave;
tideSave=function(){tideDeep.shop=nightShop;shopSaveBase();};
function shopVisit(id){if(!shopLocations.includes(id))return false;if(!nightShop.visited.includes(id))nightShop.visited.push(id);shopPlace=id;tideSave();return true;}
function shopCall(choice){if(!['answer','ask','hang'].includes(choice))return false;if(!nightShop.events.includes('ring')){shopFeedback='听筒里是断续的忙音。玻璃门上的雨还没停。';return false;}if(choice==='ask'&&!nightShop.calls.includes('answer'))return false;if(!nightShop.calls.includes(choice))nightShop.calls.push(choice);nightShop.callStage=nightShop.events.includes('second')?2:1;tideSave();return true;}
function shopStreetMap(){return `<section class="night-shop"><header><small>原创虚构城市 / 雾江 / 2008</small><h2>旧巷手机修理铺</h2><p>你来替老板看一晚店。三部旧手机充着电，柜台上压着没填完的回访单。</p></header><nav class="shop-map" aria-label="雾江旧巷探索地图"><div class="shop-river">海堤 / 水道</div><div class="shop-street"></div>${[['counter','旧巷手机店','柜台与回访单'],['bench','维修工作台','旧手机与工具'],['bus','东站公交亭','末班车与留言'],['quay','旧海堤外侧','只到警示线外']].map(([id,title,sub])=>`<button class="map-${id}" data-shop-place="${id}"><b>${title}</b><span>${sub}</span>${nightShop.visited.includes(id)?'<small>来过</small>':''}</button>`).join('')}</nav>${shopPlace?shopPlaceMarkup():`<p class="shop-intro">街灯亮了又暗。玻璃门外没有人，门铃却晃了一下。你可以先把店里的东西看一遍。</p>`}<footer><button data-shop-phones>看看充电的手机</button><button data-shop-call="answer">${nightShop.visited.length>=2?'座机指示灯亮了 · 接听':'拿起柜台的座机'}</button><button data-shop-close>回到刚才的画面</button></footer><details><summary>关于这个场景</summary><p>这是虚构城市中的探索故事，地图不是现实导航。午夜时间、短信和电话均为游戏内事件，不拨打真实号码，不申请麦克风或通知权限，不自动响铃。当前可完整游玩的手机故事为潮声扩展篇；其他地点作为可探索场景和后续线索。</p></details></section>`;}
function shopPlaceMarkup(){const pages={counter:`<h3>玻璃柜台</h3><p>老板把“失物”两个字划掉，改成“待确认”。有的手机是客人送修的，有的是买来的，不是每一部都该交给第一个来问的人。</p><p>一张回访便条写着：“许同学，海边录音那部。号码打不通，先留着。”背面还有四个字：别催他回。</p><details><summary>填写这张回访单</summary>${shopFeedback?`<p role="status">${escapeHTML(shopFeedback)}</p>`:''}${nightShop.returned?'<p>已登记：暂存原件，等待核实归还。未把未知声音来源写成事实。</p>':`<form data-shop-return><label>这部手机的姓名<input name="name" aria-label="回访单姓名" maxlength="20"></label><label>记在便条上的爱好<select name="habit"><option value="">还不确定</option><option value="field">环境声音采集</option><option value="photo">毕业摄影</option><option value="band">乐队排练</option></select></label><button>先记入回访簿</button></form>`}</details>`,bench:`<h3>木头工作台</h3><p>银色6600的后盖贴着乐队贴纸，白色5230包在洗照片的信封里。黑色N73没有写名字，卡槽里还有一张存储卡。</p><p>这些手机里的年份不同，装的软件和常去的网页也不同。你把它们各放在一块旧鼠标垫上，避免装错后盖。</p><button data-shop-phones>给一部手机开机</button>`,bus:`<h3>东站公交亭</h3><p>末班车22:40，去老码头。雨把车窗上的广告泡皱了，只有四块钱的票价还清楚。</p><p>亭子的留言板上有人写：“那个人拿着录音机，一直没上车。”下面另一种笔迹回：“我看到的只有手机。”</p><button data-shop-place="counter">回到手机店</button>`,quay:`<h3>旧海堤外侧</h3><p>你停在警示线外。灯塔和检修口隔着很远，不应该把它们当作同一个地方。</p><p>门前的牌子写着S-04。风从水面吹上来，听不清敲击来自门后还是栏杆。你没有越过警示线。</p><p>店里的座机，在你记住这个牌子以后又亮了一次。</p><button data-shop-call="answer">查看店里留下的来电记录</button>`};return `<article class="shop-place">${pages[shopPlace]||''}</article>`;}
function shopCallMarkup(){return `<section class="night-shop"><header><small>午夜来电 / 剧情记录</small><h2>座机听筒</h2></header><article class="shop-place"><p>${nightShop.calls.includes('answer')?'听筒里先有一阵转轴声。随后，一个很近的声音说：“你们那边……现在也在下雨吗？”':'你拿起听筒，里面没有拨号音。'}</p>${nightShop.calls.includes('ask')?'<p>你问他是谁。那边沉默了一会儿，传来你白天说过的半句话：“旧手机能修好吗？”</p><p>老板说他没有装通话录音。</p>':''}${nightShop.events.includes('second')?'<p>这一次没有转轴声。有人隔着很远的水面数数，数到十七就停了。你没有报出自己的名字。</p>':''}${nightShop.calls.includes('hang')?'<p>你放下了听筒。玻璃门外的街灯还亮着，指示灯熄了。你仍可以继续查看记录。</p>':''}</article><footer><button data-shop-call="ask">问他是谁</button><button data-shop-call="hang">放下听筒</button><button data-shop-map>放回听筒 / 看看店里</button></footer><small>无自动声音，电话只在游戏文字中发生。</small></section>`;}
function openShop(){dialog('雾江 / 旧巷手机修理铺',shopMap());}
const shopEntranceBase=renderPhoneEntrance,shopWorkbenchBase=renderWorkbench;
renderPhoneEntrance=function(){return `<section class="shop-entry"><small>夜班 / 手机与街巷的故事</small><h2>雾江市 · 旧巷手机店</h2><p>有些客人来修手机，有些只想取回以前留下的东西。</p><button data-shop-map>推开玻璃门</button></section>`+shopEntranceBase();};
renderWorkbench=function(){return `<button class="shop-map-entry" data-shop-map>进入旧巷手机店</button>`+shopWorkbenchBase();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-shop-map],[data-shop-place],[data-shop-phones],[data-shop-close],[data-shop-call],[data-shop-object],[data-shop-take],[data-shop-action],[data-shop-street]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-shop-street'))return dialog('雾江 / 街巷',shopStreetMap());if(b.dataset.shopObject){shopInspect(b.dataset.shopObject);return openShop();}if(b.dataset.shopTake){shopTake(b.dataset.shopTake);return openShop();}if(b.dataset.shopAction){shopAct(b.dataset.shopAction);return openShop();}if(b.hasAttribute('data-shop-close'))return document.querySelector('#modal')?.close();if(b.hasAttribute('data-shop-phones'))return dialog('工作台上的旧手机',tideShelf());if(b.dataset.shopPlace){shopVisit(b.dataset.shopPlace);return openShop();}if(b.dataset.shopCall){if(!shopCall(b.dataset.shopCall))return openShop();return dialog('午夜来电 / 本机剧情',shopCallMarkup());}shopAdvance();openShop();});
function shopReturn(name,habit){if(!tideDeep.talk.includes('hello')||!tide.seen.includes('qq'))return '这只是便条上的姓。还没有足够的记录，不能把两个人当成同一个人。';if(String(name||'').trim()!=='许舟'||habit!=='field')return '这和手机里的称呼或生活记录对不上。先留空也可以。';nightShop.returned=true;tideSave();return '回访单已登记。原件留在店里，不交给未经核实的来访者。';}
document.addEventListener('submit',e=>{if(!e.target.matches('[data-shop-return]'))return;e.preventDefault();const f=new FormData(e.target);shopFeedback=shopReturn(f.get('name'),f.get('habit'));openShop();document.querySelector('.shop-place details')?.setAttribute('open','');});

// Scene objects are explored independently; no objective arrows or automatic audio.
let shopObject='';
function shopAdvance(){
 const hadRing=nightShop.events.includes('ring');
 if(!hadRing&&nightShop.items.includes('case')&&tideDeep.read.includes('recorder')&&tideDeep.talk.includes('hello'))nightShop.events.push('ring');
 if(hadRing&&nightShop.calls.includes('hang')&&tideDeep.read.includes('repairlog')&&!nightShop.events.includes('sms'))nightShop.events.push('sms');
 if(nightShop.events.includes('sms')&&tideDeep.read.includes('mirror')&&tideDeep.read.includes('ledger')&&!nightShop.events.includes('second'))nightShop.events.push('second');
 tideSave();
}
function shopInspect(id){if(!['counter','tray','drawer','clock','door','poster','phone','case'].includes(id))return false;shopObject=id;shopFeedback='';if(!nightShop.inspected.includes(id))nightShop.inspected.push(id);tideSave();return true;}
function shopTake(id){if(id==='key'&&shopObject==='tray'||id==='receipt'&&shopObject==='counter'||id==='case'&&shopObject==='drawer'&&nightShop.drawer){if(!nightShop.items.includes(id))nightShop.items.push(id);shopFeedback='你把它收进了随身的布袋。';tideSave();return true;}return false;}
function shopAct(id){if(id==='unlock'&&shopObject==='drawer'){if(!nightShop.items.includes('key')){shopFeedback='锁舌卡着。铜把手上有一道新的划痕。';return false;}nightShop.drawer=true;shopFeedback='钥匙转了半圈。抽屉里是干燥的木屑味。';tideSave();return true;}return false;}
function shopObjectMarkup(){const has=k=>nightShop.items.includes(k);const pages={
 counter:`<h3>玻璃柜台 / 近看</h3><p>玻璃下面压着泛黄的贴膜价目表，边角卷起。收银盘下面露出一张被折成四折的小票。</p><div class="shop-paper">旧巷维修 / 10月19日<br>存储卡接触不良 · 不格式化<br>机身尾号：…731<br>取件人签名被水洇开了。</div>${has('receipt')?'<p>小票已经收好。</p>':'<button data-shop-take="receipt">抽出小票</button>'}<details><summary>翻开柜台上的回访簿</summary>${(()=>{shopPlace='counter';return shopPlaceMarkup()})()}</details>`,
 tray:`<h3>充电器托盘</h3><p>圆口充电器缠在一起。一枚小铜钥匙压在万能充的透明夹片下面，线缆把它勒出一道深痕。</p><div class="shop-prop-key">♧ ━━━⊏</div>${has('key')?'<p>夹片下面只留下了浅浅的印子。</p>':'<button data-shop-take="key">拨开电线，拿起钥匙</button>'}`,
 drawer:`<h3>柜台右侧抽屉</h3>${nightShop.drawer?`<div class="shop-drawer-open"><span>保修卡 / 旧电池 / 透明盒</span></div><p>几张过期保修卡下面有一个透明磁带盒。盒子里没有磁带，衬纸写着“17”，旁边的日期只剩下2005。</p>${has('case')?'<p>空盒子已放入布袋。</p>':'<button data-shop-take="case">拿起透明盒</button>'}`:'<div class="shop-drawer-closed">▰</div><p>上层抽屉锁着。下层只剩几个掉漆的模型机。</p><button data-shop-action="unlock">试试抽屉的锁</button>'}`,
 clock:'<h3>石英钟</h3><p>23:48。秒针在十二的位置顿了一下，又走过去。老板把换电池的日期写在钟侧：昨天。</p>',
 door:'<h3>玻璃门</h3><p>贴膜广告的背面透着街灯。门铃上挂着一根鱼线，另一头早就断了。雨水沿着“营业中”的字往下流。</p><button data-shop-street>隔着门看看街巷</button>',
 poster:'<h3>褪色的促销页</h3><div class="shop-paper">彩屏时代 · 音乐随身<br>128MB 存储卡 / 来电大头贴<br>发送代码下载彩铃<br>学生凭证换膜八折</div><p>广告已经晒成蓝紫色。右下角写着一个人的排班时间，星期三那栏被反复擦过。</p>',
 phone:'<h3>维修垫上的手机</h3><p>银色手机旁边是乐队贴纸，黑色那部缺一张保修单。白色触屏手机的照片袋整齐地压在后盖下。</p><button data-shop-phones>拿起一部，按下电源</button>',
 case:'<h3>布袋里的透明盒</h3><div class="shop-paper">17<br>2005 / …02<br>衬纸背面：雨声不是同一天录的。</div><p>盒子边沿有一小块不透明的胶痕，像是曾经贴过另一张编号。</p>'};return shopObject?`<article class="shop-closeup">${pages[shopObject]||''}${shopFeedback?`<p role="status">${escapeHTML(shopFeedback)}</p>`:''}<button data-shop-object="door">抬头看看门口</button></article>`:'';}
function shopMap(){const ring=nightShop.events.includes('ring')&&(!nightShop.calls.includes('hang')||nightShop.events.includes('second')&&nightShop.callStage<2);return `<section class="night-shop shop-immersive"><header><small>雾江市 / 旧巷 / 夜班</small><h2>旧巷手机修理铺</h2><p>雨沿着门缝钻进来。日光灯亮着，三部手机还在充电。</p></header><div class="shop-room" aria-label="手机店内景，可点物件查看"><div class="room-wall"></div><div class="room-floor"></div><div class="room-shelf"><i></i><i></i><i></i><i></i><i></i><span>配件 · 维修</span></div><button class="room-door" data-shop-object="door" aria-label="查看玻璃门"><span>旧巷手机</span><b>营业中</b></button><button class="room-clock" data-shop-object="clock" aria-label="查看墙上石英钟">◷<small>23:48</small></button><button class="room-poster" data-shop-object="poster" aria-label="查看墙上旧广告">彩屏时代<br><b>音乐随身</b><span>学生八折</span></button><div class="room-bench"></div><button class="room-tray" data-shop-object="tray" aria-label="查看充电器托盘"><i>⌁⌁</i><span>万能充</span></button><button class="room-phones" data-shop-object="phone" aria-label="查看维修台上的旧手机"><i>▦</i><i>▦</i><i>▤</i></button><button class="room-counter" data-shop-object="counter" aria-label="近看玻璃柜台"><span class="glass-stock">电池　数据线　存储卡</span><span class="paper-slip">维修凭证</span></button><button class="room-drawer ${nightShop.drawer?'is-open':''}" data-shop-object="drawer" aria-label="查看柜台抽屉"><span>━</span></button><button class="room-landline ${ring?'is-ringing':''}" data-shop-call="answer" aria-label="拿起柜台座机"><b>☎</b><i></i></button><span class="room-light"></span></div><p class="shop-room-caption">${ring?'座机上的小红灯，在玻璃上留下一点倒影。':'只有充电器的电流声。物件可以点开近看。'}</p><nav class="shop-bag" aria-label="随身布袋"><span>布袋</span>${nightShop.items.map(k=>`<button data-shop-object="${{key:'tray',receipt:'counter',case:'case'}[k]}">${{key:'小铜钥匙',receipt:'维修小票',case:'透明盒'}[k]}</button>`).join('')||'<small>空的</small>'}</nav>${shopObjectMarkup()}${shopFeedback&&!shopObject?`<p role="status">${escapeHTML(shopFeedback)}</p>`:''}<footer><button data-shop-street>看看店外</button><button data-shop-close>回到手中的手机</button></footer><details><summary>场景与声音设置</summary><p>原创虚构故事。电话与短信仅在游戏中发生，无自动响铃。进度保存在本机，可在存档盒导出。</p></details></section>`;}
const shopSmsBase=tideSms;
tideSms=function(){const base=shopSmsBase();if(tide.device!=='black'||!nightShop.events.includes('sms'))return base;if(tideView==='shop:message')return tideFrame('未知号码 / 00:13',`<div class="deep-chat"><p>00:13 · 本机收到</p><p>你把盒子拿起来的时候，那边安静了一下。</p><p>我说的是以前。不是今晚。</p><p>发送时间：2005-11-02 00:13<br>接收时间：2008-10-20 00:13</p></div>${tideBtn('sms','返回收件箱')}`);return base.replace('<div class="deep-contact-list">','<div class="deep-contact-list"><button data-shop-message>未知号码 · 00:13<br>我说的是以前。</button>');};
document.addEventListener('click',e=>{if(!e.target.closest('[data-shop-message]'))return;tideView='shop:message';refreshPhone();});
